import type { EngineInterface, Register } from 'claude-code'

// Avisa (sonido + notificación de escritorio) cuando la sesión queda esperando a Dani:
// terminó el turno, o pide permiso / hace una pregunta. Nunca mientras hay agentes laburando.

const SONIDOS = '/home/dani/mods/aviso-fin/sonidos'
const VIVOS = new Set(['pending', 'running', 'waiting'])
const ANTIREBOTE_MS = 15000
// tool.check da «ask» antes de que el modo lo resuelva: en modo auto/plan lo aprueba el clasificador
// sin mostrarte nada. Solo es un diálogo real si la herramienta sigue sin arrancar pasado este rato.
const ESPERA_PERMISO_MS = 6000

let ultimoAviso = 0
const resueltos = new Set<string>() // tool_use_id que ya corrieron
const arrancados = new Set<string>() // tool_use_id ejecutando (pastilla ctrl+b del Bash)

export function primeraLinea(texto: string | undefined, max = 120): string {
  const linea = (texto ?? '').split('\n').map(l => l.replace(/[*_`#>]/g, '').trim()).find(l => l) ?? ''
  return linea.length > max ? `${linea.slice(0, max - 1)}…` : linea
}

function carpeta(cwd: string): string {
  return cwd.split('/').filter(Boolean).pop() ?? cwd
}

// De qué se trata la sesión, muy breve: el repo si el cwd está en uno; si no, la tarea
// (el primer mensaje de Dani); y si tampoco, la carpeta.
async function lugar($: EngineInterface): Promise<string> {
  const cwd = await $.session.cwd()
  try {
    const r = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { cwd, timeoutMs: 3000 })
    const repo = r.exitCode === 0 ? r.stdout.trim() : ''
    if (repo) return carpeta(repo)
  } catch {}
  try {
    const tarea = primeraLinea((await $.session.messages()).find(m => m.role === 'user' && m.text?.trim())?.text, 40)
    if (tarea) return tarea
  } catch {}
  return carpeta(cwd)
}

async function hayAgentesVivos($: EngineInterface): Promise<boolean> {
  try {
    return (await $.agent.list()).some(a => VIVOS.has(a.status))
  } catch {
    return false
  }
}

async function avisar($: EngineInterface, sonido: string, titulo: string, cuerpo: string, critico = false) {
  const ahora = Date.now()
  if (ahora - ultimoAviso < ANTIREBOTE_MS) return
  ultimoAviso = ahora
  const donde = await lugar($)
  $.process.run(['paplay', `${SONIDOS}/${sonido}`]).catch(() => {})
  $.process
    .run(['notify-send', '-a', 'Claude Code', '-i', 'dialog-information', '-u', critico ? 'critical' : 'normal', `${titulo} · ${donde}`, cuerpo])
    .catch(() => {})
}

export const register: Register = on => {
  // Fin del turno del loop principal (agentId presente = turno de un subagente).
  // OJO: los classic.* (Stop, Notification) los saltea cc-plugin-sec-default para mods de usuario.
  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined && !(await hayAgentesVivos($))) {
      if (e.reason === 'error' || e.reason === 'refusal') {
        await avisar($, 'fin.ogg', 'Claude se frenó (error)', primeraLinea(e.answer) || 'Se cortó el turno.', true)
      } else {
        await avisar($, 'fin.ogg', 'Claude terminó', primeraLinea(e.answer) || 'Listo.')
      }
    }
    return r
  })

  // Marca las llamadas que arrancaron (permiso dado, por vos o por el clasificador).
  // Se marca antes de next: una herramienta que tarda más de ESPERA_PERMISO_MS no es un permiso trabado.
  on('tool.call', async ($, e, next) => {
    if (resueltos.size > 500) resueltos.clear()
    resueltos.add(e.tool_use_id)
    return next(e)
  })

  // La pastilla «ctrl+b to run in background» sale solo con el Bash ya ejecutando.
  on('ui.render', { component: 'ToolProgress' }, ($, e, next) => {
    if (arrancados.size > 500) arrancados.clear()
    arrancados.add(e.props.tool_use_id)
    return next(e)
  })

  // Una herramienta queda esperando tu permiso: se avisa solo si sigue trabada pasado ESPERA_PERMISO_MS.
  on('tool.check', async ($, e, next) => {
    const r = await next(e)
    const id = e.tool_use_id
    // agentId (ask dentro de un subagente) existe desde 2.1.291; en engines previos no viene y lo cubre hayAgentesVivos.
    const agentId = (e as { agentId?: string }).agentId
    if (r.decision === 'ask' && id !== undefined && agentId === undefined) {
      $.clock.after(ESPERA_PERMISO_MS, () => {
        const corrio = resueltos.delete(id)
        const arranco = arrancados.delete(id)
        if (corrio || arranco) return
        hayAgentesVivos($)
          .then(vivos => (vivos ? undefined : avisar($, 'pregunta.ogg', 'Claude te necesita', `Pide permiso para ${e.tool}.`)))
          .catch(() => {})
      })
    }
    return r
  })

  // Te hace una pregunta o te presenta un plan.
  on('tool.call', { tool: ['AskUserQuestion', 'ExitPlanMode'] }, async ($, e, next) => {
    if (!(await hayAgentesVivos($))) {
      await avisar($, 'pregunta.ogg', 'Claude te necesita', e.tool === 'AskUserQuestion' ? 'Te hace una pregunta.' : 'Plan listo para aprobar.')
    }
    return next(e)
  })
}

